# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">UNIT 4: COMMUNICATION HABITS, SMARTPHONE APPS &amp; EMERGENCY CALLS</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Smartphone Applications (Apps) &amp; Pros/Cons</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#1e3a8a">• find your way / use GPS navigation (yön bulmak)</text>\n  <text x="180" y="114" text-anchor="middle" font-size="11" fill="#1e3a8a">• translate foreign sentences (çeviri yapmak)</text>\n  <text x="180" y="134" text-anchor="middle" font-size="11" fill="#1e3a8a">• do online shopping / pay the bills (fatura ödemek)</text>\n  <text x="180" y="154" text-anchor="middle" font-size="11" fill="#1e3a8a">• order food / book a flight ticket (bilet ayırtmak)</text>\n  <text x="180" y="174" text-anchor="middle" font-size="11" fill="#1e3a8a">• practice foreign languages / improve vocabulary</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">+ Pros: fast, easy to carry, saves time, rescue</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">- Cons: addiction, eye strain, security risks</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Emergency Calls &amp; Public Services (112)</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" fill="#881337">• What is your emergency? (Acil durumunuz nedir?)</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" fill="#881337">• Report a fire / traffic accident / burglary / medical</text>\n  <text x="520" y="134" text-anchor="middle" font-size="11" fill="#881337">• Please stay calm and share your exact location.</text>\n  <text x="520" y="154" text-anchor="middle" font-size="11" fill="#881337">• We are sending an ambulance / fire brigade right now.</text>\n  <text x="520" y="176" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">Customer Service / Call Center:</text>\n  <text x="520" y="196" text-anchor="middle" font-size="11" fill="#881337">• Make a complaint (şikâyet) · Return a broken product</text>\n  <text x="520" y="216" text-anchor="middle" font-size="11" fill="#881337">• Ask for a refund / delivery information</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PHONE CONVERSATION SEQUENCING &amp; MEMO (NOTE) STRUCTURE</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Steps of a Phone Conversation</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#14532d">1. Greeting &amp; Intro: Hello, this is Jane calling.</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11" fill="#14532d">2. Asking for Someone: May I speak to Mr. Brown?</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" fill="#14532d">3. Holding / Availability: Hold on a moment, please.</text>\n  <text x="180" y="160" text-anchor="middle" font-size="11" fill="#14532d">4. Unavailable: I\'m afraid he isn\'t available now.</text>\n  <text x="180" y="182" text-anchor="middle" font-size="11" fill="#14532d">5. Taking a Message: Would you like to leave a message?</text>\n  <text x="180" y="204" text-anchor="middle" font-size="11" fill="#14532d">6. Closing Decision: Could you tell him to call me back?</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">7. Ending: Sure, I\'ll let him know. Have a nice day!</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Sample Phone Memo (Not Kağıdı)</text>\n  <text x="385" y="98" font-size="11" font-weight="bold" fill="#713f12">• To (Alıcı / Kime):</text>\n  <text x="515" y="98" font-size="11" fill="#854d0e">Mr. Kevin Brown</text>\n  <text x="385" y="122" font-size="11" font-weight="bold" fill="#713f12">• From (Arayan / Kimden):</text>\n  <text x="535" y="122" font-size="11" fill="#854d0e">Jane Miller</text>\n  <text x="385" y="146" font-size="11" font-weight="bold" fill="#713f12">• Date &amp; Time:</text>\n  <text x="515" y="146" font-size="11" fill="#854d0e">December 15 — 14:30</text>\n  <text x="385" y="170" font-size="11" font-weight="bold" fill="#713f12">• Phone Number:</text>\n  <text x="515" y="170" font-size="11" fill="#854d0e">0555 123 45 67</text>\n  <text x="385" y="194" font-size="11" font-weight="bold" fill="#713f12">• Message:</text>\n  <text x="455" y="194" font-size="11" fill="#854d0e">The project meeting is at 10 a.m.</text>\n  <text x="385" y="216" font-size="11" fill="#854d0e">tomorrow. Please call her back as soon as possible.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">INTRODUCTION TO UNIT 5: THE INTERNET — HABITS &amp; VOCABULARY</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Core Internet Vocabulary</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#164e63">• log in / log on (giriş yapmak) x log out / off (çıkış)</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11" fill="#164e63">• sign up / register (kayıt olmak, hesap açmak)</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" fill="#164e63">• upload (dosya yüklemek) x download (dosya indirmek)</text>\n  <text x="180" y="160" text-anchor="middle" font-size="11" fill="#164e63">• attachment (ek dosya) · browser (tarayıcı)</text>\n  <text x="180" y="182" text-anchor="middle" font-size="11" fill="#164e63">• search engine (arama motoru) · confirm (onaylamak)</text>\n  <text x="180" y="204" text-anchor="middle" font-size="11" fill="#164e63">• delete (silmek) · comment (yorum yapmak)</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">• connection sign / Wi-Fi / broken modem</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Asking About Internet Habits</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">• For what purposes do you use the Internet?</text>\n  <text x="520" y="116" text-anchor="middle" font-size="11" fill="#581c87">I use it to do research, read articles and check emails.</text>\n  <text x="520" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">• How do you connect to the Internet?</text>\n  <text x="520" y="162" text-anchor="middle" font-size="11" fill="#581c87">I usually connect via my smartphone or laptop.</text>\n  <text x="520" y="188" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">• Who uses the Net most in your family?</text>\n  <text x="520" y="208" text-anchor="middle" font-size="11" fill="#581c87">My brother does; he plays online games for hours.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
